"""T145: inventory_I.json -> RACE_SHADER_INVENTORY.md (hashes and metadata only, no shader text)."""
import json, sys
d = json.load(open(sys.argv[1])); out = open(sys.argv[2], 'w', encoding='utf-8')
fps, vps = d['fps'], d['vps']
out.write('# T145 race shader inventory (RSXI capture I, frames f006502 + f006527)\n\n'
          'Source: `t113/runtime-I-20261027-182926/rsxi` (T113 arm I). Generated by `tools/inventory.py` + `tools/inventory_md.py`.\n'
          'Hashes and metadata only. Units = texture units the decompiled body fetches (S Sample, B SampleBias, L SampleLevel, '
          'sh depth-compare helper). Flags: P predicated (exec_if/CC), K kill, W WPOS read, Q perspective-corrected texcoord, '
          'F facing, X bx2 fetch, A fp16/fp32 alias sync, M MRT (targets), D depth export. sRGB = draws asking SET_SHADER_PACKER '
          'sRGB output; gamma = draws fetching a unit with a texture-gamma mask. Unsupported opcodes (TODO): none in any program.\n\n'
          '| fp | code hash | instrs | draws | passes (colour target) | units | inputs | flags | sRGB | gamma (unit:mask=draws) |\n'
          '|---|---|---|---|---|---|---|---|---|---|\n')
ab = {'Sample': 'S', 'SampleBias': 'B', 'SampleLevel': 'L', 'shadow': 'sh', 'SampleGrad': 'G'}
for fp, m in sorted(fps.items(), key=lambda a: -a[1].get('draws', 0)):
    units = ' '.join('%s%s' % (u, ''.join(ab.get(h, h) for h in hs)) for u, hs in m.get('units', {}).items())
    fl = ''.join(c for c, k in (('P', 'predicated'), ('K', 'kill'), ('Q', 'persp'), ('X', 'bx2_fetches'),
                                ('A', 'alias_sync'), ('D', 'depth_export')) if m.get(k))
    if 'position' in m.get('inputs', []) and not m.get('persp'): fl += 'W'
    if '_rsx_front' in m.get('inputs', []): fl += 'F'
    if m.get('targets', 1) > 1: fl += 'M%d' % m['targets']
    ins = ','.join(i for i in m.get('inputs', []) if i != 'position')
    g = ' '.join('%s=%d' % kv for kv in m.get('gamma_fetch_draws', {}).items())
    out.write('| %s | %s | %s | %d | %s | %s | %s | %s | %d | %s |\n' % (
        fp, m.get('code_hash'), m.get('instrs'), m.get('draws', 0), ' '.join(m.get('passes', [])), units, ins, fl,
        m.get('srgb_output_draws', 0), g))
out.write('\n## Vertex programs\n\n| vs hash | instrs | attributes read | outputs written | branches |\n|---|---|---|---|---|\n')
for h, m in sorted(vps.items(), key=lambda a: -(a[1].get('instrs') or 0)):
    out.write('| %s | %s | %s | %s | %s |\n' % (h, m['instrs'], ' '.join(map(str, m['attrs'])), ' '.join(map(str, m['outputs'])), m['branches']))
